import scipy.stats as stats

# Calculate p-values for the correlation coefficients
p_values = {}
for col in df.columns:
    if col != 'BAMM_speciation':
        corr, p = stats.pearsonr(df['BAMM_speciation'], df[col])
        p_values[col] = p

# Identify variables with a weak but significant, positive relationship
significant_weak_positive = []
for col in df.columns:
    if col != 'BAMM_speciation' and p_values[col] < 0.05 and stats.pearsonr(df['BAMM_speciation'], df[col])[0] > 0.00003018:
        significant_weak_positive.append(col)

